const body = $input.first().json;
const query = body.query || body.args || '';
const chatId = body.chatId;

if (!query.trim()) {
  throw new Error('Query vazia. Use: /buscar <tema>');
}

// Enriquece a busca com termos de futebol brasileiro
const enrichedQuery = `${query} futebol brasil site:youtube.com`;

return [{ json: { query, enrichedQuery, chatId } }];

const response = $input.first().json;
const items = response.items || [];
const query = $('Preparar Query').first().json.query;
const chatId = $('Preparar Query').first().json.chatId;

if (items.length === 0) {
  return [{ json: { videos: [], query, chatId, message: `Nenhum vídeo encontrado para "${query}".` } }];
}

// Filtra vídeos com duração razoável (canais de futebol BR)
// e formata para inserção no banco
const videos = items.map(item => ({
  youtubeVideoId: item.id.videoId,
  title: item.snippet.title,
  channelId: item.snippet.channelId,
  channelName: item.snippet.channelTitle,
  publishedAt: item.snippet.publishedAt,
  description: item.snippet.description,
  thumbnailUrl: item.snippet.thumbnails?.high?.url || item.snippet.thumbnails?.default?.url
}));

return [{ json: { videos, query, chatId } }];

const { videos, query, chatId } = $input.first().json;
const now = new Date().toISOString();

// Gera queries SQL para inserção
// Primeiro verifica/insere os canais, depois insere os vídeos
const upsertChannelQueries = [];
const insertVideoQueries = [];

const channelsSeen = new Set();

videos.forEach(v => {
  if (!channelsSeen.has(v.channelId)) {
    channelsSeen.add(v.channelId);
    upsertChannelQueries.push({
      channelId: v.channelId,
      channelName: v.channelName,
      rssUrl: `https://www.youtube.com/feeds/videos.xml?channel_id=${v.channelId}`
    });
  }

  insertVideoQueries.push({
    youtubeVideoId: v.youtubeVideoId,
    channelId: v.channelId,
    title: v.title.replace(/'/g, "''"),
    publishedAt: v.publishedAt
  });
});

return [{ json: { upsertChannelQueries, insertVideoQueries, query, chatId, total: videos.length } }];
